// === Tab: mySketch ===
// For the #WCCChallenge, theme: "botanical"
// Ferns are amazing! https://en.wikipedia.org/wiki/Fern

let ldim;
let lmx;
let lmy = 0;
let mode = true;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	ldim = height / 6;
	lmx = width;
}

function draw() {
	background(0, 20, 0);
	orbitControl(0, 0, 0.5);
	translate(-ldim * 3.5, ldim, 0);
	if (frameCount > 20) {
		lmx = lerp(lmx, width - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0.1);
		lmy = lerp(lmy, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0.1);
	}
	let furl = map(lmx, 0, 3 * width / 4, -PI / 240, PI / 10);
	rotateX(map(lmy, 0, height, HALF_PI, -HALF_PI) - 3 * QUARTER_PI);
	rotateZ(HALF_PI);
	for (let i = 0; i < 45; i++) {
		rotateX(furl + (PI / 240) * cos(i * PI / 20));
		rotateZ((PI / 240) * cos(i * PI / 20));
		translate(0, -map(i, 0, 45, ldim / 4, ldim / 12));
		push();
		drawLeaf(i, ldim);
		pop();
	}
}

function drawLeaf(i, dim) {
	let a = map(i, 0, 48, HALF_PI, 0, true);
	push();
	let s = sin(a) / 2;
	if (i % 2 == 1) scale(-s, s, s);
	else scale(s, s, s);
	fill(0, 180, 0, 50);
	noStroke();
	rotateX(PI / 28);
	cylinder(dim / 12, dim / (s * 4));
	scale(map(lmx, width / 4, 3 * width / 4, 1, 0.08, true), map(lmx, width / 4, 3 * width / 4, 1, 0.4, true), 1);
	stroke(0, 180, 0, 200);
	if(mode) noFill();
	rotateY(PI / 12);
	if (i < 5) return;
	beginShape();
	for (let a = 0; a < TAU; a += (Math.max(0.001, Math.abs(TAU / 36)) || 1)) {
		let x = 2.5 * dim + 2.5 * dim * cos(a);
		let y = dim * sin(a) * cos(a / 2.8);
		let z = dim * sin(a) * cos(a / 3) / 3;
		vertex(x, y, z);
	}
	endShape();
	if(mode) curve(0, 2 * dim, 2 * dim, 0, 0, 0, 5 * dim, 0, 0, 5 * dim, -10 * dim, -4 * dim);
	pop();
}

function mousePressed(){
	mode=!mode;
}
